-- =============================================
-- Rota haritası için koordinatlar
-- 1) WorldCities tablosu enlem/boylam ile yeniden oluşturulur
-- 2) TripStops'a enlem/boylam sütunları eklenir ve mevcut duraklar doldurulur
-- =============================================
USE TravelTrackerDb;
GO

DROP TABLE WorldCities;
GO

CREATE TABLE WorldCities (
    Id          INT            PRIMARY KEY,
    CountryIso  CHAR(3)        NOT NULL,
    Name        NVARCHAR(200)  NOT NULL,
    Population  INT            NOT NULL,
    Latitude    DECIMAL(9,5)   NOT NULL,   -- enlem
    Longitude   DECIMAL(9,5)   NOT NULL    -- boylam
);
GO

CREATE INDEX IX_WorldCities_Country ON WorldCities (CountryIso, Name);
GO

SET NOCOUNT ON;
GO
GO
