GO
GO
GO
GO
GO
GO

ALTER TABLE TripStops ADD Latitude DECIMAL(9,5) NULL, Longitude DECIMAL(9,5) NULL;
GO

-- Önceden eklenmiş durakların koordinatlarını şehir tablosundan doldur
UPDATE ts
SET ts.Latitude = wc.Latitude, ts.Longitude = wc.Longitude
FROM TripStops ts
CROSS APPLY (
    SELECT TOP 1 Latitude, Longitude
    FROM WorldCities
    WHERE CountryIso = ts.CountryIso
      AND Name COLLATE Latin1_General_CI_AI = ts.Place COLLATE Latin1_General_CI_AI  -- İstanbul = Istanbul
    ORDER BY Population DESC
) wc;
GO

SELECT (SELECT COUNT(*) FROM WorldCities) AS Sehirler,
       (SELECT COUNT(*) FROM TripStops WHERE Latitude IS NOT NULL) AS KonumuBulunanDuraklar;
GO
